function EXTRA(R,ICON){
 /* hook: the braking drive sends its energy back through the bridge to the mains */
 ICON.peDrive=(x,y)=>`<g transform="translate(${x} ${y})">
  <circle cx="-160" cy="-30" r="62" fill="#FFFFFF" stroke="${BLU}" stroke-width="5"/>${PE_T(-160,-14,'M',{fs:52,fw:800,a:'middle',fill:BLU})}${PE_T(-160,62,'DC machine',{fs:24,fw:800,a:'middle',fill:BLU})}
  ${PE_box(-50,-96,110,130,{fill:'#E3FAF1',st:ACC,sw:4,r:14})}${PE_scr(5,-40,26,INK,4)}${PE_T(5,62,'bridge',{fs:24,fw:800,a:'middle'})}
  ${PE_box(110,-82,130,104,{fill:'#FFFFFF',st:GRN,sw:4,r:14})}${PE_curve(t=>Math.sin(t),0,2*Math.PI,124,226,-30,30,GRN,5,40)}${PE_T(175,62,'mains',{fs:24,fw:800,a:'middle',fill:GRN})}
  ${PE_arrow(-96,-30,-58,-30,ORG,6)}${PE_arrow(66,-30,104,-30,ORG,6)}
  ${PE_T(0,140,'energy: DC → AC',{fs:28,fw:800,a:'middle',fill:ORG})}</g>`;
 /* recap pictures: each fills most of its card (about 420 × 330) */
 ICON.peOverlap=(x,y)=>{const f=PE_notch;return `<g transform="translate(${x-210} ${y-165})">${PE_T(0,24,'vo',{fs:26,fw:800,fill:BLU})}${PE_L(40,120,420,120,PE_GR,2)}${PE_area(t=>Math.sin(PE_rad(t)),30,47.7,0,180,40,420,120,90,ORG,.5)}${PE_curve(t=>{const m=t;return (m>=30&&m<=47.7)?0:(m<30?-Math.sin(PE_rad(m)):Math.sin(PE_rad(m)))},0,180,40,420,120,90,BLU,5,180)}
  ${PE_T(0,206,'is',{fs:26,fw:800,fill:GRN})}${PE_L(40,262,420,262,PE_GR,2)}<polyline points="40,312 103,312 140,212 420,212" fill="none" stroke="${GRN}" stroke-width="5" stroke-linejoin="round"/>
  ${PE_L(103,190,103,330,PE_MU,2,'stroke-dasharray="4 6"')}${PE_L(140,190,140,330,PE_MU,2,'stroke-dasharray="4 6"')}${PE_T(122,322,'μ',{fs:28,fw:800,a:'middle',fill:ORG})}</g>`};
 ICON.peQuad=(x,y)=>`<g transform="translate(${x-210} ${y-165})">${PE_quad(210,165,190,150,26)}<circle cx="320" cy="80" r="14" fill="${BLU}"/>${PE_arrow(320,96,320,232,ORG,6)}<circle cx="320" cy="250" r="14" fill="${ORG}"/>${PE_T(300,88,'rectifier',{fs:24,fw:800,a:'end',fill:BLU})}${PE_T(300,258,'inverter',{fs:24,fw:800,a:'end',fill:ORG})}</g>`;
 ICON.peLimit=(x,y)=>`<g transform="translate(${x-210} ${y-165})">${PE_T(0,30,'100 A',{fs:26,fw:800,fill:BLU})}${PE_bar(10,410,46,58,[[148.7,BLU,'α 148.7°'],[16.3,ORG,''],[15,GRN,'']],24)}${PE_T(0,170,'20 A',{fs:26,fw:800,fill:BLU})}${PE_bar(10,410,186,58,[[160.7,BLU,'α 160.7°'],[4.3,ORG,''],[15,GRN,'']],24)}${PE_T(10,290,'μ',{fs:28,fw:800,fill:ORG})}${PE_T(40,290,'grows with Id;',{fs:24,fw:700,fill:PE_MU})}${PE_T(10,324,'γ₀ = 15° always kept',{fs:24,fw:700,fill:GRN})}</g>`;
}
